H.background();
const w = H.W, h = H.H;
const va = Math.max(0, P.volA);
const vb = Math.max(0, P.volB);
const ca = H.clamp(P.concA, 0, 100) / 100;
const cb = 0.50;
const total = Math.max(1e-6, va + vb);
const mixC = (va * ca + vb * cb) / total;
const baseY = h * 0.80, maxH = h * 0.46, maxV = 12;
function beaker(cx, vol, conc, label, col) {
  const bw = 70;
  const bh = (Math.min(vol, maxV) / maxV) * maxH;
  H.rect(cx - bw / 2, baseY - maxH, bw, maxH, { stroke: H.colors.grid, width: 1.5 });
  H.rect(cx - bw / 2, baseY - bh, bw, bh, { fill: col, radius: 2 });
  const ph = bh * conc;
  H.rect(cx - bw / 2, baseY - ph, bw, ph, { fill: H.colors.accent2, radius: 2 });
  H.text(label, cx, baseY + 20, { color: H.colors.ink, size: 13, align: "center", weight: 700 });
  H.text(vol.toFixed(1) + " L @ " + (conc * 100).toFixed(0) + "%", cx, baseY + 38, { color: H.colors.sub, size: 11, align: "center" });
}
const pulse = 0.5 + 0.5 * Math.sin(t * 2);
beaker(w * 0.22, va, ca, "A", H.colors.accent);
beaker(w * 0.50, vb, cb, "B", H.colors.violet);
beaker(w * 0.80, total, mixC, "Mix", H.hsl(180, 50, 45 + 8 * pulse));
H.arrow(w * 0.30, baseY - maxH * 0.5, w * 0.40, baseY - maxH * 0.5, { color: H.colors.good, width: 2 });
